create or replace function sourceenergy_one.create_knowledge_cycle(p_subject_id text,p_title text,p_context jsonb,p_consent_scope_id text,p_actor_ref text,p_prior_cycle_id uuid default null) returns uuid language plpgsql security definer set search_path=sourceenergy_one,pg_temp as $$ declare cid uuid; begin if nullif(btrim(p_subject_id),'') is null or nullif(btrim(p_consent_scope_id),'') is null or nullif(btrim(p_actor_ref),'') is null then raise exception 'subject, consent scope and actor required'; end if; if p_prior_cycle_id is not null and not exists(select 1 from sourceenergy_one.knowledge_cycles where id=p_prior_cycle_id and subject_id=p_subject_id) then raise exception 'prior cycle does not belong to subject'; end if; insert into sourceenergy_one.knowledge_cycles(subject_id,title,context,consent_scope_id,prior_cycle_id,actor_ref) values(btrim(p_subject_id),p_title,coalesce(p_context,'{}'::jsonb),btrim(p_consent_scope_id),p_prior_cycle_id,btrim(p_actor_ref)) returning id into cid; insert into sourceenergy_one.audit_events(correlation_id,subject_id,actor_id,event_type,object_type,object_ref,payload) values(gen_random_uuid(),btrim(p_subject_id),auth.uid(),'seci_cycle_created','knowledge_cycle',cid::text,jsonb_build_object('phase','socialize','consent_scope_id',btrim(p_consent_scope_id),'actor_ref',btrim(p_actor_ref))); return cid; end $$;

create or replace function sourceenergy_one.add_knowledge_artifact(p_cycle_id uuid,p_phase text,p_artifact_type text,p_protected_content jsonb,p_visibility text,p_source_refs jsonb,p_actor_ref text) returns uuid language plpgsql security definer set search_path=sourceenergy_one,pg_temp as $$ declare c sourceenergy_one.knowledge_cycles%rowtype; aid uuid; h text; begin select * into c from sourceenergy_one.knowledge_cycles where id=p_cycle_id for update; if not found or c.status<>'active' then raise exception 'active knowledge cycle required'; end if; if p_phase<>c.current_phase then raise exception 'artifact phase must equal current SECI phase'; end if; if p_visibility not in ('private','cycle_only','reflection_only','approved_derived_use') then raise exception 'invalid visibility'; end if; if nullif(btrim(p_artifact_type),'') is null or nullif(btrim(p_actor_ref),'') is null then raise exception 'artifact type and actor required'; end if; if p_protected_content is null or jsonb_typeof(p_protected_content)<>'object' then raise exception 'protected content object required'; end if; h:=encode(extensions.digest(convert_to(p_protected_content::text,'UTF8'),'sha256'::text),'hex'); insert into sourceenergy_one.knowledge_artifacts(cycle_id,subject_id,phase,artifact_type,protected_content,content_hash,consent_scope_id,visibility,source_refs,actor_ref) values(c.id,c.subject_id,p_phase,btrim(p_artifact_type),p_protected_content,h,c.consent_scope_id,p_visibility,coalesce(p_source_refs,'[]'::jsonb),btrim(p_actor_ref)) returning id into aid; return aid; end $$;

create or replace function sourceenergy_one.advance_knowledge_cycle(p_cycle_id uuid,p_to_phase text,p_evidence_artifact_ids uuid[],p_rationale text,p_actor_ref text) returns uuid language plpgsql security definer set search_path=sourceenergy_one,pg_temp as $$ declare c sourceenergy_one.knowledge_cycles%rowtype; tid uuid; expected text; begin select * into c from sourceenergy_one.knowledge_cycles where id=p_cycle_id for update; if not found or c.status<>'active' then raise exception 'active knowledge cycle required'; end if; expected:=case c.current_phase when 'socialize' then 'externalize' when 'externalize' then 'combine' when 'combine' then 'internalize' when 'internalize' then 'socialize' end; if p_to_phase<>expected then raise exception 'invalid SECI transition: % -> %',c.current_phase,p_to_phase; end if; if p_evidence_artifact_ids is null or cardinality(p_evidence_artifact_ids)=0 then raise exception 'transition evidence required'; end if; if exists(select 1 from unnest(p_evidence_artifact_ids) x(id) left join sourceenergy_one.knowledge_artifacts a on a.id=x.id where a.id is null or a.cycle_id<>c.id or a.phase<>c.current_phase) then raise exception 'transition evidence must belong to current phase and cycle'; end if; if nullif(btrim(p_rationale),'') is null or nullif(btrim(p_actor_ref),'') is null then raise exception 'rationale and actor required'; end if; insert into sourceenergy_one.knowledge_transitions(cycle_id,subject_id,from_phase,to_phase,evidence_artifact_ids,rationale,actor_ref) values(c.id,c.subject_id,c.current_phase,p_to_phase,p_evidence_artifact_ids,btrim(p_rationale),btrim(p_actor_ref)) returning id into tid; update sourceenergy_one.knowledge_cycles set current_phase=p_to_phase,updated_at=now() where id=c.id; return tid; end $$;

revoke all on function sourceenergy_one.create_knowledge_cycle(text,text,jsonb,text,text,uuid) from public,anon,authenticated; revoke all on function sourceenergy_one.add_knowledge_artifact(uuid,text,text,jsonb,text,jsonb,text) from public,anon,authenticated; revoke all on function sourceenergy_one.advance_knowledge_cycle(uuid,text,uuid[],text,text) from public,anon,authenticated;
grant execute on function sourceenergy_one.create_knowledge_cycle(text,text,jsonb,text,text,uuid) to service_role; grant execute on function sourceenergy_one.add_knowledge_artifact(uuid,text,text,jsonb,text,jsonb,text) to service_role; grant execute on function sourceenergy_one.advance_knowledge_cycle(uuid,text,uuid[],text,text) to service_role;
